// Package mail is the control plane for MH-577: team mail servers. Like internal/dbsvc it is the one
// implementation the REST API and the MCP share, so validation, roles, audit and "a secret never
// leaves in a list" are written once.
//
// A team mail server is one Stalwart Mail Server container run by the agent on one of the team's
// servers (internal/agentproto mail.* kinds, internal/agent/mail.go). The admin credential and every
// mailbox password are generated by Hosbah, sealed at rest with the team DEK, and re-sealed to the
// target agent's own key for each operation, so operations.params never holds a plaintext secret. A
// mailbox password is returned to the caller exactly once, at creation or reset, and never again.
package mail

import (
	"context"
	"crypto/rand"
	"crypto/sha256"
	"database/sql"
	"encoding/hex"
	"encoding/json"
	"errors"
	"log/slog"
	"math/big"
	"time"

	"github.com/fadymondy/hosbah/internal/app"
	db "github.com/fadymondy/hosbah/internal/db/gen"
	"github.com/fadymondy/hosbah/internal/deploy"
	"github.com/fadymondy/hosbah/internal/ops"
	"github.com/fadymondy/hosbah/internal/tenancy"
)

// Actor is who asked (reused from deploy so audit reads the same across phases).
type Actor = deploy.Actor

// Error carries an HTTP status for the REST layer; the MCP layer just shows the message.
type Error struct {
	Status  int
	Message string
}

func (e *Error) Error() string { return e.Message }

func notFound(what string) error { return &Error{Status: 404, Message: what + " not found"} }
func invalid(msg string) error   { return &Error{Status: 422, Message: msg} }
func conflict(msg string) error  { return &Error{Status: 409, Message: msg} }

// Service runs the mail control plane.
type Service struct {
	a      *app.App
	ops    *ops.Service
	deploy *deploy.Service
	log    *slog.Logger
}

// New builds the service. deploy is used for its team Cloudflare credential lookup (PublishDNS).
func New(a *app.App, o *ops.Service, d *deploy.Service) *Service {
	log := a.Log
	if log == nil {
		log = slog.Default()
	}
	return &Service{a: a, ops: o, deploy: d, log: log.With("component", "mail")}
}

func (s *Service) App() *app.App { return s.a }

// sys runs a system+team transaction (background workers): app.system for the SELECT/UPDATE
// policies, and app.team_id so the team FOR ALL policy admits an INSERT/UPDATE of the team's rows.
func (s *Service) sys(ctx context.Context, teamID string, fn func(q *db.Queries) error) error {
	return tenancy.Tx(ctx, s.a.SQLDB, tenancy.Scope{System: true, TeamID: teamID}, func(q *db.Queries, _ *sql.Tx) error { return fn(q) })
}

func (s *Service) spawn(fn func(context.Context)) {
	go func() {
		ctx, cancel := context.WithTimeout(context.Background(), 15*time.Minute)
		defer cancel()
		fn(ctx)
	}()
}

// ---- operation plumbing ------------------------------------------------------------------------

// withServer resolves the server's agent key and team DEK, lets build() produce the params + op id,
// then enqueues and awaits the signed operation, decoding its result into out.
func (s *Service) withServer(ctx context.Context, teamID, serverID string, build func(agentKey string, dek []byte) (any, string, error), kind string, out any) error {
	var agentKey string
	var dek []byte
	if err := s.sys(ctx, teamID, func(q *db.Queries) error {
		k, err := q.ServerTeamKey(ctx, serverID)
		if err != nil {
			return err
		}
		if k.AgentPublicKey == nil {
			return errors.New("the server's agent has not enrolled")
		}
		agentKey = *k.AgentPublicKey
		dek, err = s.a.Keys.UnwrapDEK(k.TeamID, k.DekWrapped)
		return err
	}); err != nil {
		return err
	}
	params, id, err := build(agentKey, dek)
	if err != nil {
		return err
	}
	if err := s.sys(ctx, teamID, func(q *db.Queries) error {
		if _, err := q.OperationInTeam(ctx, db.OperationInTeamParams{ID: id, TeamID: teamID}); err == nil {
			return nil // resume: it already exists
		}
		raw, _ := json.Marshal(params)
		_, _, e := s.ops.Enqueue(ctx, q, ops.EnqueueSpec{OpID: id, TeamID: teamID, ServerID: serverID, Kind: kind, Params: raw, CreatedBy: "hosbah"})
		return e
	}); err != nil {
		return err
	}
	s.ops.Wake()
	done, err := s.ops.Await(ctx, id, serverID, nil)
	if err != nil {
		return err
	}
	if done.Status != "ok" {
		if done.Error != nil {
			return errors.New(*done.Error)
		}
		return errors.New(done.Status)
	}
	if out != nil && done.Result != nil {
		return json.Unmarshal([]byte(*done.Result), out)
	}
	return nil
}

// ---- helpers -------------------------------------------------------------------------------------

func adminSealContext(mailServerID string) string { return "mailadmin:" + mailServerID }
func mailboxSealContext(mailboxID string) string  { return "mailbox:" + mailboxID }

// opID derives a stable operation id from an entity and a step, so a resumed action re-attaches
// instead of racing a second copy of itself. "cloudy-mail" is a fixed seed, like dbsvc's "cloudy-db".
func opID(entityID, step string) string {
	sum := sha256.Sum256([]byte("cloudy-mail\n" + entityID + "\n" + step))
	b := sum[:16]
	b[6] = (b[6] & 0x0f) | 0x40
	b[8] = (b[8] & 0x3f) | 0x80
	h := hex.EncodeToString(b)
	return h[0:8] + "-" + h[8:12] + "-" + h[12:16] + "-" + h[16:20] + "-" + h[20:32]
}

func mustJSON(v any) []byte { b, _ := json.Marshal(v); return b }

const pwAlphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"

func randPassword(n int) string {
	b := make([]byte, n)
	for i := range b {
		k, _ := rand.Int(rand.Reader, big.NewInt(int64(len(pwAlphabet))))
		b[i] = pwAlphabet[k.Int64()]
	}
	return string(b)
}

func newUUID() string {
	var b [16]byte
	_, _ = rand.Read(b[:])
	b[6] = (b[6] & 0x0f) | 0x40
	b[8] = (b[8] & 0x3f) | 0x80
	h := hex.EncodeToString(b[:])
	return h[0:8] + "-" + h[8:12] + "-" + h[12:16] + "-" + h[16:20] + "-" + h[20:32]
}

func strptr(s string) *string {
	if s == "" {
		return nil
	}
	return &s
}

func derefStr(p *string) string {
	if p == nil {
		return ""
	}
	return *p
}

// auditExtra builds an audit detail map from the actor's exported fields.
func auditExtra(a Actor, extra map[string]any) map[string]any {
	if extra == nil {
		extra = map[string]any{}
	}
	if a.Via != "" && a.Via != "web" {
		extra["via"] = a.Via
	}
	if a.TokenID != "" {
		extra["mcp_token_id"] = a.TokenID
	}
	return extra
}

// teamDEK is a small wrapper so callers do not reach into s.ops directly.
func (s *Service) teamDEK(ctx context.Context, q *db.Queries, teamID string) ([]byte, error) {
	return s.ops.TeamDEK(ctx, q, teamID)
}

func destinationsJSON(dests []string) string {
	if dests == nil {
		dests = []string{}
	}
	out, _ := json.Marshal(dests)
	return string(out)
}

func parseDestinations(raw string) []string {
	var out []string
	_ = json.Unmarshal([]byte(raw), &out)
	return out
}
